// Title: How to enable gridlines in HTML output when converting an Excel workbook with Aspose.Cells for .NET
// Common Searches: Aspose.Cells C# export Excel to HTML with gridlines visible | set HtmlSaveOptions.ExportGridLines true in .NET | show Excel cell borders in HTML generated by Aspose.Cells | C# code to save workbook as HTML with gridlines enabled | Aspose.Cells HTML conversion preserving gridlines
// Tags: Aspose.Cells HtmlSaveOptions ExportGridLines | HTML export with gridlines C# | Excel to HTML conversion Aspose.Cells | Enable gridlines in HTML output .NET | Aspose.Cells workbook save as HTML

using System;
using System.IO;
using Aspose.Cells;
using Aspose.Cells.Saving;

// Loads an Excel workbook, configures HtmlSaveOptions.ExportGridLines to true, ensures the output folder exists, and saves the workbook as an HTML file where the gridlines are displayed.
class Program
{
    static void Main()
    {
        try
        {
            const string inputPath = "input.xlsx";
            const string outputPath = "output.html";

            // Verify that the source workbook exists to avoid FileNotFoundException
            if (!File.Exists(inputPath))
            {
                Console.WriteLine($"Error: The file '{inputPath}' was not found.");
                return;
            }

            // Load the workbook from the specified file
            Workbook workbook = new Workbook(inputPath);

            // Configure HTML save options to display gridlines
            HtmlSaveOptions htmlOptions = new HtmlSaveOptions
            {
                ExportGridLines = true // Enable gridlines in the HTML output
            };

            // Ensure the output directory exists
            string outputDir = Path.GetDirectoryName(outputPath);
            if (!string.IsNullOrEmpty(outputDir) && !Directory.Exists(outputDir))
            {
                Directory.CreateDirectory(outputDir);
            }

            // Save the workbook as an HTML file with the configured options
            workbook.Save(outputPath, htmlOptions);
            Console.WriteLine($"Workbook successfully saved as HTML to '{outputPath}'.");
        }
        catch (Exception ex)
        {
            // Catch any unexpected errors and display a friendly message
            Console.WriteLine($"An error occurred: {ex.Message}");
        }
    }
}
